import{b as O,u as S,a as C,r as n,j as o}from"./index-Crha1dSC.js";import{B as N,P as M}from"./PageLayout-5tJ8VNHW.js";import{t as p,R as A,a as z}from"./ResultBlockWithSettings-Drd8RFVW.js";import{M as L}from"./Marks-CUl88-sS.js";const R="1.0.1",U="2026-04-10",E=JSON.parse('[{"code":"em04","id":"cloud-em04","description":{"ru":"<p><i><b>Тёмные тучи сгустились на горизонте. Перед глазами вспыхнули видения молний, и вы приготовились к тому, что огонь может распространиться.</b></i></p><p>Можете потратить <lore>, чтобы получить <major_boost> к <conviction>.</p>","en":""},"marks":[],"icon":"cloud","code-ru":"БР04"},{"code":"em08","id":"cloud-em08","description":{"ru":"<p><i><b>Шаги чудища сотрясали землю до самого основания. От его могучих толчков содрогался даже небосвод и облака в ужасе рассеивались. Вы вслушались в отголоски.</b></i></p><p>До конца следующего дня стоимость изучения чудища снижена до <lore><lore>.</p>","en":""},"marks":[],"code-ru":"БР08","icon":"cloud"},{"code":"em09","id":"cloud-em09","icon":"cloud","description":{"ru":"<p><i><b>Шаги чудища сотрясали землю до самого основания. От его могучих толчков содрогался даже небосвод и облака в ужасе рассеивались. Вы вслушались в отголоски.</b></i></p><p>До конца следующего дня стоимость изучения чудища снижена до <lore><lore>.</p>","en":""},"code-ru":"БР09"},{"code":"em10","id":"cloud-em10","icon":"cloud","description":{"ru":"<p><b><i>В облаках возник лик древнего предка. Видение закружилось на мгновение — и исчезло.</i></b></p><p>Если у общины есть карта знаний «Легенды» (ЗБ15), можете потратить <lore>, чтобы получить карту легенды.</p>","en":""},"code-ru":"БР10"},{"code":"vw03","id":"cloud-vw03","icon":"cloud","description":{"ru":"<p><i><b>Глупо было отправляться на сухие равнины пустоши. Странные узоры заманили вас туда, но что вы надеялись там найти? Уж точно не воду…</b></i></p><p>Получите 1 глину, а также <minor_boost> к <conviction> и <awareness>. Затем сбросьте 2 воды или потеряйте <energy>.</p>","en":""},"code-ru":"ВП03"},{"code":"it52","id":"cloud-it52","icon":"cloud","description":{"ru":"<p><i><b>В тишине вы размышляли о значении облаков. Иногда они казались огромными твёрдыми горами в небе, а в другие моменты начинали яростно крутиться, принося дождь. Облака заставили вас задуматься о том, что такое сила, незыблемость и перемены. Возможно, вам следовало оставить здесь небольшую пирамиду из камней в качестве напоминания.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Сложите небольшую пирамиду из камней, размышляя о своей жизни.</b> Если на карте вашего персонажа есть отметка становления, добавьте <lore>.<br><b>Б. Снимите с себя талисман и положите его на верх пирамиды, завершив этим одну из личных историй.</b> Сбросьте карту предмета «Талисман из облачного камня» (ВЩ52). Если сделали это, навсегда увеличьте значение <might> своего персонажа на 1 (не более чем до 7) и добавьте ему черту «отважный». Добавьте отметку становления на сторону легенды карты своего персонажа.</p>","en":""},"code-ru":"ВЩ52","marks":[{"label":"","image":"growth"}]},{"code":"fm06","id":"cloud-fm06","icon":"cloud","description":{"ru":"<p><i><b>Под небольшим кустом вы заметили пустующее гнездо. Неожиданно вас осенило, что клубящиеся туманы могут скрыть вас, пока вы поджидаете хозяина этого гнезда.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Отметьте гнездо и продолжите путь.</b> Добавьте <lore>, затем продолжите добычу припасов.<br><b>Б. Разорите гнездо в поисках припасов. </b>Прекратите добычу припасов и получите 1 дичь, 1 коренье, 1 перо и 1 волокно.</p>","en":""},"code-ru":"ДД06"},{"code":"ff01","id":"cloud-ff01","icon":"cloud","description":{"ru":"<p><i><b>Гонимое ветром облако притянуло ваш взгляд, указав на надвигающуюся гряду бурь.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Вы знали по опыту: такие облака означают, что вскоре у вас будет много питьевой воды. </b>Если на стене первобытной пещеры есть отметка <cloud>, можете потратить <energy>, чтобы получить 2 воды.<br><b>Б. Вы решили, что бури сыграют вам на руку.</b> Проведите проверку <awareness>, чтобы оценить шансы собрать ресурсы. +2, если вы <i>изобретательный</i>, и +2, если вы <i>хитрый</i>. <br><b>≥12:</b>  Вы знали, что перед дождём животные прячутся в укрытия. Вскоре вам повезло найти отличное логово! Прекратите добычу припасов и получите 2 дичи, 1 кость и 1 шкуру. Затем на стене первобытной пещеры изобразите историю о рыданиях неба, включив в неё отметку <cloud>.<br><b>9-11:</b>  Облака предвещали дождь, а значит, и чистую воду. Вы расстелили пустую сумку и стали ждать под деревом. Получите 2 воды, затем продолжите добычу припасов.<br><b>1-8:</b>  Это было всего лишь облако. Вы запомнили его очертания и пошли дальше. Получите <lore> и продолжите добычу припасов.</p>","en":""},"code-ru":"ДЛ01"},{"code":"fg10","id":"cloud-fg10","icon":"cloud","description":{"ru":"<p><i><b>Вы поняли, что в тени плывущего мимо облака можно скрыться от хищников.</b></i></p><p>Можете провести проверку <awareness>, чтобы скрыться от хищника. +2, если вы <i>хитрый</i>.<br><b>≥7:</b>  Уберите любую карту с хищником из своей области добычи.<br><b>1-6:</b>  Ваша попытка скрыться оказалась тщетной. Прекратите добычу припасов и встретьтесь с хищником.</p>","en":""},"code-ru":"ДП10"},{"code":"fp12","id":"cloud-fp12","icon":"cloud","description":{"ru":"<p><i><b>Когда зверь‑охотник надвигался на вас, над вашей головой скользнула тень. Что это? Грозовая туча с равнины? Знамение придало вам смелости, и хищник, похоже, ощутил вашу силу.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Ударьте зверя в уязвимое место, о котором вы знали.</b> Если на стене первобытной пещеры есть отметка зверобоя, получите <major_boost> к <might> или <dexterity>, затем встретьтесь с хищником.<br><b>Б. Столкнитесь со зверем. </b>Получите <minor_boost> к <might> или <dexterity>, затем встретьтесь с хищником. Добавьте к целям карту «Пройдите испытание охотника» (ЦA05).</p>","en":""},"marks":[{"label":"","image":"beastslayer"}],"code-ru":"ДС12"},{"code":"kn04","id":"cloud-kn04","icon":"cloud","description":{"ru":"<p><b><i>Надвигалось облако, несущее в долину дождь. Вы задумались о том, как бы собрать эту воду…</i></b></p><p>Спроектируйте дождесборник (СР15), не тратя <energy>.</p>","en":""},"code-ru":"ЗБ04"},{"code":"ca05","id":"cloud-ca05","icon":"cloud","description":{"ru":"<p><i><b>Горизонт затянулся облачной дымкой, и вы задумались, не пора ли полить посевы.</b></i></p><p>Если на карте цели «Посейте семена процветания» есть хотя бы 1 жетон, можете сбросить 3 воды, чтобы добавить на эту карту ещё 1 такой жетон.</p>","en":""},"code-ru":"ИA05"},{"code":"cb08","id":"cloud-cb08","icon":"cloud","description":{"ru":"<p><b><i>Над горами ползли зловещие тучи. Это не сулило ничего хорошего.</i></b></p><p>Можете потратить <lore>, чтобы получить <major_boost> к любой характеристике.</p>","en":""},"code-ru":"ИБ08"},{"code":"cc04","id":"cloud-cc04","icon":"cloud","description":{"ru":"<p><i><b>Огромные клубы пыли заполонили долину, и передвигаться по ней стало рискованно. Возможно, под землёй будет безопаснее?</b></i></p><p>До конца следующего дня, если у общины есть карта знаний «Спуск» (ЗБ07), можете тратить <lore> вместо <energy>, чтобы выполнять действие спуска.</p>","en":""},"code-ru":"ИВ04"},{"code":"cz08","id":"cloud-cz08","icon":"cloud","description":{"ru":"<p><i><b>Могучий рёв чудищ прокатывался над долиной, словно гром. Остерегайтесь — лучше не попадаться им под ноги.</b></i></p><p>Можете потратить <lore>, чтобы получить <major_boost> к <dexterity>.</p>","en":""},"code-ru":"ИЯ08"},{"code":"ja04","id":"cloud-ja04","icon":"cloud","description":{"ru":"<p><i><b>Вместо того чтобы попытаться определить направление или расстроиться из‑за неудачи, вы унеслись мыслями к далёким облакам в небе. Они плывут без цели, как огромные горы, унесённые ветром, но всегда доходят туда, куда стремятся. Вы так же позволили ветру направлять вас и продолжили свой путь.</b></i></p><p>Вместо того чтобы разыгрывать эту карту пути, получите <energy>. Затем разыграйте первое, что можете:<br><b>А. Проследуйте за ветром по знакомому пути. </b>Если на стене первобытной пещеры есть отметка <cloud>, добавьте <lore>. <br><b>Б. Тщательно запомните путь, который вам открыл ветер.</b> На стене первобытной пещеры изобразите историю о вздымающемся ветре, включив в неё отметку <cloud> и отметку тайны.</p>","en":""},"code-ru":"ПA04","marks":[{"label":"","image":"mystery"}]},{"code":"jy05","id":"cloud-jy05","icon":"cloud","description":{"ru":"<p><i><b>Вам показалось, что в облаках скоро появится просвет. Если сможете продержаться ещё немного, возможно, станет теплее. </b></i></p><p>При розыгрыше этой карты пути можете провести проверку <conviction> вместо <might>. После проверки, независимо от результата, можете потратить <lore>, чтобы <outcome> 990.</p>","en":""},"code-ru":"ПЕ05"},{"code":"je05","id":"cloud-je05","icon":"cloud","description":{"ru":"<p><i><b>Облака кружили, играя пятнами света на холме. Но на горизонте вы заметили нечто ещё более занимательное…</b></i></p><p>Вместо того чтобы разыгрывать эту карту пути, поместите жетон тайны на любой участок местности без персонажа.</p>","en":""},"code-ru":"ПР05"},{"code":"je07","id":"cloud-je07","icon":"cloud","description":{"ru":"<p><i><b>Дым от костров вашего народа пробудил в вас ярость, которая нарастала, подобно грозовому облаку.</b></i></p><p>Получите <major_boost> к <conviction>.</p>","en":""},"code-ru":"ПР07"},{"code":"jm01","id":"cloud-jm01","icon":"cloud","description":{"ru":"<p><i><b>Вы заметили шёлковую нить, стелющуюся от гигантского усика шагающего хребта и похожую на пушистое белое облачко. Потянув за неё, вы, возможно, смогли бы управлять этим существом!</b></i></p><p>Если значение <might> персонажа равно хотя бы 4, при розыгрыше этой карты пути можете выбрать любой участок местности вместо случайного.</p>","en":""},"code-ru":"ПУ01"},{"code":"jm02","id":"cloud-jm02","icon":"cloud","description":{"ru":"<p><i><b>Не уклоняясь от обжигающего тумана, вы прикрыли лицо одеждой и позволили его горячим клубам пройти мимо.</b></i></p><p>Ваша община получает силу мантии «Бредущий в тумане» (MA19).</p>","en":""},"code-ru":"ПУ02"},{"code":"jm05","id":"cloud-jm05","icon":"cloud","description":{"ru":"<p><i><b>Вы следовали тропами, прокладываемыми в тумане порывами ветров, и достигли своей цели.</b></i></p><p>После розыгрыша этой карты пути поместите своего персонажа на любой участок Ураганных холмов (не берите новую карту пути).</p>","en":""},"code-ru":"ПУ05"},{"code":"jb01","id":"cloud-jb01","icon":"cloud","description":{"ru":"<p><i><b>В тайнике вы нашли… </b></i></p><p>Разыграйте первое, что можете:<br><b>А. …что-то поистине уникальное.</b> Если в долине есть активное логово чудища, вместо того чтобы разыгрывать карту пути, отложите соответствующие карты предметов (см. ниже), не рассматривая их лицевые стороны (если эти карты недоступны, перейдите к пункту «Б»). Если у любого персонажа есть трофеи, в названиях которых есть слова, общие со словами из названий этих предметов, исключите эти карты из отложенных.<br><bh1>: ВЩ85, ВЩ86<br><bh2>: ВЩ87, ВЩ88 <br><bh3>: ВЩ92, ВЩ93<br><bh4>:ВЩ99, ВЩ100<br><b>Б. …странные отметки, которые вас озадачили.</b> Добавьте <lore><lore>.</p>","en":""},"code-ru":"ПЧ01"},{"code":"jb04","id":"cloud-jb04","icon":"cloud","description":{"ru":"<p><i><b>Кружившие над головой облака сложились в очертания огромных ликов.</b></i></p><p>Добавьте <lore>.</p>","en":""},"code-ru":"ПЧ04"},{"code":"pv10","id":"cloud-pv10","icon":"cloud","description":{"ru":"<p><i><b>Облако скользило над водой, предвещая перемену погоды.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Найдите предзнаменования в облаках. </b>Добавьте <lore>.<br><b>Б. Изучите ненастье.</b> Потратьте <lore>, чтобы посмотреть 3 верхние карты колоды пути и положить любое количество из них под низ колоды.</p>","en":""},"code-ru":"РД10"},{"code":"ps03","id":"cloud-ps03","icon":"cloud","description":{"ru":"<p><i><b>В мутной воде вы разглядели отражение облака, хотя в тёмном небе над вами не было видно ни одного. Вы нырнули в глубину и достали нечто полезное…</b></i></p><p>Можете выполнить действие раскопок (не тратя <energy>), дополнительно добавив в мешочек лунную кровь.</p>","en":""},"code-ru":"РЗ03"},{"code":"st13","id":"cloud-st13","icon":"cloud","description":{"ru":"<p><i><b>С высоты памятника вы наблюдали, как с горизонта надвигалась огромная грозовая туча, идеально обрамлённая круглым порталом в центре каменного изваяния. В этой туче скрывалась вся мощь стихии.</b></i></p><p>Получите <major_boost> к <might>.</p>","en":""},"code-ru":"СР13"},{"code":"vv02","id":"cloud-vv02","icon":"cloud","description":{"ru":"<p><i><b>Перед вами в гору взмывала огромная спираль из лиан, её вершина скрывалась в грозовых облаках. Ярость небес потрескивала в кристаллических шипах побегов, и вы чувствовали, как она пронизывает землю под ногами. Рискнёте ли вы взобраться на самый верх?</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Смиритесь с тем, что небо — удел облаков. </b>Если на стене первобытной пещеры есть отметка <cloud>, получите <major_boost> к <conviction>.<br><b>Б. Устремитесь к высочайшим вершинам. </b>Проведите проверку <might>, чтобы взобраться по лианам. +2, если вы <i>хитрый</i>, и +2, если у вас есть «Верёвка».<br><b>≥12:</b>  Вы взбирались долгие часы, уклоняясь от бушующей грозы. На вершине вы окинули взором долину. Можете взять любой неисследованный участок местности, рассмотреть его в течение 30 секунд и вернуть обратно неисследованной стороной вверх. Затем на стене первобытной пещеры изобразите историю о великом восхождении, включив в неё отметку <cloud> и отметку открытия.<br><b>9-11:</b>  Вы с трудом добрались до середины пути, но решили, что благоразумие важнее, и вернулись. Потеряйте <energy> и получите <major_boost> к <awareness>.<br><b>1-8:</b>  Вы успели преодолеть лишь часть пути, когда вас сбросило на землю ударом молнии. Получите <major_injury><major_injury> и добавьте <lore><lore>.</p>","en":""},"code-ru":"УД02","marks":[{"label":"","image":"discovery"}]},{"code":"sp06","id":"cloud-sp06","icon":"cloud","description":{"ru":"<p><i><b>Грозовое облако, нависшее над вами, приняло очертания черепа без челюсти. Сквозь сухой воздух зловеще потрескивали молнии. Встретиться с этой бурей означало взглянуть в лицо самой смерти.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Встретьте бурю, чтобы доказать свою стойкость.</b> Бросьте <1d6> и разыграйте исход по результату броска:<br><b>1:</b>  Получите <major_injury><major_injury><major_injury><major_injury>. Добавьте отметку несчастья на сторону легенды карты своего персонажа.<br><b>2-6:</b>  Получите черту «неукротимый» и <major_boost> к любой характеристике. Добавьте отметку <cloud> на сторону легенды карты своего персонажа.<br><b>Б. Скройтесь в низинах, пока буря не пройдёт.</b> Получите <minor_boost> к любой характеристике.</p>","en":""},"code-ru":"УП06","marks":[{"label":"","image":"misfortune"}]},{"code":"tt07","id":"cloud-tt07","icon":"cloud","description":{"ru":"<p><i><b>Извивающиеся корни образовали странный узор — возможно, они оплетали нечто, чего здесь больше нет?</b></i></p><p>Получите 1 волокно и <major_boost> к <awareness>. Добавьте карту «Падение пожелтевших листьев» (ИЖ02) к грядущим испытаниям, если ещё не завершили это испытание.</p>","en":""},"code-ru":"УС07"},{"code":"pr01a","id":"cloud-pr01a","icon":"cloud","description":{"ru":"<p><i><b>Вам всюду виделись облака: не только в небе, где они могли принимать разные облики, но и в искусстве вашего народа и в очертаниях самой долины. И хоть они казались вездесущими, иногда облако — это просто облако. Но и в этом был свой урок: даже в обыденном может скрываться смысл, и лишь умелый наблюдатель сумеет его постичь. «Смотри, — словно говорили облака, — мы бываем бесчисленными и безобидными, но внутри нас могут таиться буря и невиданная ярость».</b></i></p><p>Без эффекта.</p>","en":""},"code-ru":"ФП01Д"},{"code":"ga11","id":"cloud-ga11","icon":"cloud","description":{"ru":"<p><i><b>Лёгкий след облаков направил ваш взгляд к чему‑то неожиданному...</b></i></p><p>Можете потратить <lore>, чтобы поместить жетон тайны на любой участок местности без персонажа, выбрав участок с горой, если возможно.</p>","en":""},"code-ru":"ЦA11"},{"code":"ga13","id":"cloud-ga13","icon":"cloud","description":{"ru":"<p><i><b>Пока долину накрывала тьма, двигающиеся облака даровали вам укрытие.</b></i></p><p>В следующий раз, когда встретитесь с чудищем в течение этого дня, можете воспринимать значение его нрава на 2 ниже (не менее 1).</p>","en":""},"code-ru":"ЦA13"},{"code":"gz16","id":"cloud-gz16","icon":"cloud","description":{"ru":"<p><i><b>Луч света, пробившийся сквозь облака, указал вам на любопытный предмет...</b></i></p><p>Если на вашем участке местности есть логово чудища, можете потратить <lore><lore>, чтобы получить 1 сокровище этого чудища.</p>","en":""},"code-ru":"ЦЯ16"},{"code":"bh1","id":"cloud-bh1","icon":"cloud","description":{"ru":"<p><i><b>Вокруг головы чудища сгустились облака, и на его каменной коже заблестели капельки росы. Чудище последовало за облаком, и по его массивным бокам заструилась вода. Неужели оно так пьёт?</b></i></p><p>Получите 2 воды.</p>","en":""},"code-ru":"ЧД1"},{"code":"it46","id":"comet-it46","icon":"comet","description":{"ru":"<p><i><b>В небесных знаках вам виделись символы знаний.</b></i></p><p>Можете потратить <energy>. Если сделали это, проведите проверку <conviction>, чтобы изучить знаки. +2, если вы <i>сосредоточенный</i>, и +4, если у вас есть отметка <comet>.<br><b>≥12:</b>  Получите <energy> и <major_boost> к <conviction>. Добавьте <energy>.<br><b>8-11:</b>  Получите <major_boost> к <conviction>. Добавьте <lore>.<br><b>1-7:</b>  В этот раз вам не удалось прочесть знаки. Без эффекта.</p>","en":""},"code-ru":"ВЩ46"},{"code":"it47","id":"comet-it47","icon":"comet","description":{"ru":"<p><i><b>В моменты тишины вы чувствовали, как коралл, висящий на вашей шее, мягко пульсировал — похоже, он пытался уловить ритм вашего сердцебиения.</b></i></p><p>Уменьшите каждый из своих недугов по одному разу.</p>","en":""},"code-ru":"ВЩ47"},{"code":"it56","id":"comet-it56","icon":"comet","description":{"ru":"<p><i><b>В тишине вы размышляли о значении комет. Они обычно являлись лишь на мгновение: то как тонкая полоса в небе, то как зловещий огненный след, сжигающий горизонт. Из‑за такой непредсказуемости природу комет было сложно изучить. Казалось, что они — это части неба, спускающиеся в долину. Вероятно, когда‑то они принадлежали этому месту. Но может, им лучше остаться в небе… Вы решили сложить небольшую пирамиду из камней, чтобы запомнить эти мысли.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Поразмышляйте о том, как путь Скитальца отражает вашу собственную жизнь. </b>Если на карте вашего персонажа есть отметка становления, добавьте <lore>.<br><b>Б. Оставьте коралловый талисман на вершине пирамиды, чтобы унести эти мысли с собой на всю жизнь.</b> Сбросьте карту предмета «Коралловый талисман» (ВЩ56). Если сделали это, навсегда увеличьте значение одной из самых низких характеристик своего персонажа на 2 (не более чем до 7) и добавьте ему черту «сосредоточенный». Добавьте отметку становления на сторону легенды карты своего персонажа.</p>","en":""},"code-ru":"ВЩ56","marks":[{"label":"","image":"growth"}]},{"code":"fp07","id":"comet-fp07","icon":"comet","description":{"ru":"<p><i><b>На грубой коре дерева вы заметили странную метку. Вы стали копать у его корней и нашли кусок перламутрового материала.</b></i></p><p>Получите 1 мёртвый коралл. Затем разыграйте первое, что можете:<br><b>А. Внимательно изучите знакомые признаки коралла.</b> Если на стене первобытной пещеры есть отметка коралла, добавьте <lore>.<br><b>Б. Копайте вокруг корней. </b>Добавьте карту «Используйте странный коралл» (ЦЯ03) к целям.</p>","en":""},"code-ru":"ДС07","marks":[{"label":"","image":"coral"}]},{"code":"cc04","id":"comet-cc04","icon":"comet","description":{"ru":"<p><i><b>Разрушительное появление Скитальца потрясло долину, и вы пытались понять, что произошло.</b></i></p><p>Можете потратить <lore>, чтобы получить <major_boost> к <awareness>.</p>","en":""},"code-ru":"ИВ04"},{"code":"cf02","id":"comet-cf02","icon":"comet","description":{"ru":"<p><i><b>Искривлённое дерево хранило на себе старый шрам в форме кометы. Этот след явно был гораздо старше недавнего внезапного роста кораллов.</b></i></p><p>Перед тем как продолжить добычу припасов, выберите и разыграйте одно:<br><b>А. Внимательно изучите след.</b> Добавьте <lore>.<br><b>Б. Изучите небо в поисках ответов. </b>Потратьте <lore>, чтобы посмотреть верхнюю карту колоды ночи, затем верните её на верх или положите под низ колоды.</p>","en":""},"code-ru":"КЛ02"},{"code":"cf04","id":"comet-cf04","icon":"comet","description":{"ru":"<p><i><b>Покрытый кораллами хищник поднялся на дыбы и щёлкнул челюстями, но не атаковал сразу. Он встал между вами и коралловыми зарослями. Может быть, он защищал распространяющиеся кораллы? Была ли у вас возможность не казаться ему чужаком?</b></i></p><p>Если у вас нет предмета <i>коралла</i>, проведите встречу с хищником по обычным правилам. Если у вас есть предмет коралла, проведите проверку <conviction>, чтобы противостоять хищнику. +2, если вы <i>неукротимый</i>, и +1 за каждый живой коралл в вашем инвентаре (не более +3).<br><b>≥14:</b>  Хищник опустился на землю и наклонил голову, как бы оценивая вас. Несколько раз шевельнув рожками, он развернулся и ушёл. Верните в коробку карту КЛ04.<br><b>10-13:</b>  Хищник не двигался, но продолжал яростно щёлкать челюстями. Вы осторожно отступили. Немедленно прекратите добычу припасов.<br><b>1-9:</b>  Немедленно сразитесь с хищником (вычтите 4 из своего результата проверки).</p>","en":""},"code-ru":"КЛ04"},{"code":"cg02","id":"comet-cg02","icon":"comet","description":{"ru":"<p><i><b>Сквозь дыру в гигантском листе пробивался свет — похоже, растение чем‑то прожгло насквозь. Вы вспомнили рассказ старейшины о том, как неподалёку с неба упал огненный камень.</b></i></p><p>Перед тем как продолжить добычу припасов, выберите и разыграйте одно:<br><b>А. Внимательно изучите отметку. </b>Добавьте <lore>.<br><b>Б. Изучите небо в поисках ответов.</b> Потратьте <lore>, чтобы посмотреть верхнюю карту колоды ночи, затем верните её на верх или положите под низ колоды.</p>","en":""},"code-ru":"КП02"},{"code":"cg04","id":"comet-cg04","icon":"comet","description":{"ru":"<p><i><b>Покрытый кораллами хищник поднялся на дыбы и щёлкнул челюстями, но не атаковал сразу. Он встал между вами и коралловыми зарослями. Может быть, он защищал распространяющиеся кораллы? Была ли у вас возможность не казаться ему чужаком?</b></i></p><p>Если у вас нет предмета <i>коралла</i>, проведите встречу с хищником по обычным правилам. Если у вас есть предмет коралла, проведите проверку <conviction>, чтобы противостоять хищнику. +2, если вы <i>неукротимый</i>, и +1 за каждый живой коралл в вашем инвентаре (не более +3). <br><b>≥14:</b>  Хищник опустился на землю и наклонил голову, как бы оценивая вас. Несколько раз шевельнув усиками, он развернулся и ушёл. Верните в коробку карту КП04.<br><b>10-13:</b>  Хищник не двигался, но продолжал яростно щёлкать челюстями. Вы осторожно отступили. Немедленно прекратите добычу припасов. <br><b>1-9:</b>  Немедленно сразитесь с хищником (вычтите 4 из своего результата проверки).</p>","en":""},"code-ru":"КП04"},{"code":"cp02","id":"comet-cp02","icon":"comet","description":{"ru":"<p><i><b>Странный отпечаток среди следов животных заставил вас остановиться. Присутствие кораллов здесь было особенно заметным.</b></i></p><p>Перед тем как продолжить добычу припасов, выберите и разыграйте одно:<br><b>А. Изучите следы. </b>Добавьте <lore>.<br><b>Б. Осторожно осмотритесь вокруг.</b> Потратьте <lore>, чтобы убрать 1 карту из своей области добычи.</p>","en":""},"code-ru":"КС02"},{"code":"cp04","id":"comet-cp04","icon":"comet","description":{"ru":"<p><i><b>Покрытый кораллами хищник поднялся на дыбы и щёлкнул челюстями, но не атаковал сразу. Он встал между вами и коралловыми зарослями. Может быть, он защищал распространяющиеся кораллы? Была ли у вас возможность не казаться ему чужаком?</b></i></p><p>Если у вас нет предмета <i>коралла</i>, проведите встречу с хищником по обычным правилам. Если у вас есть предмет коралла, проведите проверку <conviction>, чтобы противостоять хищнику. +2, если вы <i>неукротимый</i>, и +1 за каждый живой коралл в вашем инвентаре (не более +3).<br><b>≥14:</b>  Хищник опустился на землю и наклонил голову, как бы оценивая вас. Несколько раз шевельнув усиками, он развернулся и ушёл. Верните в коробку карту КС04.<br><b>10-13:</b>  Хищник не двигался, но продолжал яростно щёлкать челюстями. Вы осторожно отступили. Немедленно прекратите добычу припасов.<br><b>1-9:</b>  Немедленно сразитесь с хищником (вычтите 4 из своего результата проверки).</p>","en":""},"code-ru":"КС04"},{"code":"co01b","id":"comet-co01b","icon":"comet","description":{"ru":"<p><i><b>На пыльном коралловом поле вы нашли расщелину в виде падающей кометы. </b></i></p><p>Получите 1 мёртвый коралл.</p>","en":""},"code-ru":"ОК01б"},{"code":"co02b","id":"comet-co02b","icon":"comet","description":{"ru":"<p><i><b>На пыльном коралловом поле вы нашли расщелину в виде падающей кометы. </b></i></p><p>Получите 1 мёртвый коралл.</p>","en":""},"code-ru":"ОК02б"},{"code":"co03b","id":"comet-co03b","icon":"comet","description":{"ru":"<p><i><b>На пыльном коралловом поле вы нашли расщелину в виде падающей кометы. </b></i></p><p>Получите 1 мёртвый коралл.</p>","en":""},"code-ru":"ОК03б"},{"code":"jr02","id":"comet-jr02","icon":"comet","description":{"ru":"<p><i><b>Любуясь необычным кораллом, вы не могли не задуматься о его природе…</b></i></p><p>Если на стене первобытной пещеры есть отметка коралла, добавьте <lore>. В противном случае добавьте карту «Используйте странный коралл» (ЦЯ03) к целям.</p>","en":""},"code-ru":"ПК02","marks":[{"label":"","image":"coral"}]},{"code":"ju02","id":"comet-ju02","icon":"comet","description":{"ru":"<p><i><b>Скиталец пересёк затухающий горизонт, и вы наполнились решимостью следовать за ним. Пробиваясь сквозь густые заросли, вы прокладывали собственный путь.</b></i></p><p>Ваша община получает силу мантии «Покоритель сумерек» (MA09).</p>","en":""},"code-ru":"ПН02"},{"code":"st13","id":"comet-st13","icon":"comet","description":{"ru":"<p><i><b>С высоты памятника в сумеречном небе вы заметили огненную комету, очертания которой идеально вошли в круглый проём в центре каменного монумента. Это было загадочным знамением.</b></i></p><p>Получите <major_boost> к <conviction>.</p>","en":""},"code-ru":"СР13"},{"code":"vv09","id":"comet-vv09","icon":"comet","description":{"ru":"<p><i><b>Перед вами лежала безмерно большая яичная скорлупа, расколотая и сухая. Белок такого яйца мог бы быть океаном, а желток — островом. Отгоняя мысли об изобильных землях, вы размышляли, кто мог бы вылупиться из него. В поисках безопасного места для отдыха в тени скорлупы вы нашли необычный кристаллический порошок на месте раскола.</b></i></p><p>Можете поместить жетон убежища стороной «2» вверх на свой участок местности. Затем, если вы <i>изобретательный</i>, получите предмет «Блестящий порошок» (ВЩ65), как будто вы только что изготовили его.</p>","en":""},"code-ru":"УД09"},{"code":"tt06","id":"comet-tt06","icon":"comet","description":{"ru":"<p><i><b>Над вами возвышалась огромная хитиновая оболочка. Трещина, глубоко врезавшаяся в неё, напоминала след кометы… </b></i></p><p>Можете провести проверку <conviction>, чтобы войти в трещину. +2, если у вас есть <i>талисман</i>, и +2, если вы <i>неукротимый</i>. Также +4, если потратите <lore>.<br><b>≥13:</b>  Вы ступили внутрь — и вас словно охватила ночь. Получите черту «сосредоточенный».<br><b>1-12:</b>  Вы испугались поглотившей вас тьмы. Сбегите.</p>","en":""},"code-ru":"УС06"},{"code":"mh06","id":"comet-mh06","icon":"comet","description":{"ru":"<p><i><b>Огненная, подобная магме кровь просачивалась из большой трещины на спине этого шагающего хребта. Всё существо было таким горячим, будто внутри него пылала печь.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Впитайте тепло.</b> Если на этом участке местности есть <fire>, получите <major_boost> к <might>.<br><b>Б. Понаблюдайте за тем, как трещит пламя.</b> Поместите <fire> на этот участок местности.</p>","en":""},"code-ru":"УУ06"},{"code":"em08","id":"moon-em08","icon":"moon","description":{"ru":"<p><i><b>Луна освещала долину, отдалённо и безучастно наблюдая за чудищем. Что ещё она видела за бесчисленные века? </b></i></p><p>Если в долине есть чудище с активным логовом, можете сбросить 1 его сокровище, чтобы добавить <lore><lore><lore>.</p>","en":""},"code-ru":"БР08"},{"code":"em09","id":"moon-em09","icon":"moon","description":{"ru":"<p><i><b>Луна освещала долину, отдалённо и безучастно наблюдая за чудищем. Что ещё она видела за бесчисленные века? </b></i></p><p>Если в долине есть чудище с активным логовом, можете сбросить 1 его сокровище, чтобы добавить <lore><lore><lore>.</p>","en":""},"code-ru":"БР09"},{"code":"it46","id":"moon-it46","icon":"moon","description":{"ru":"<p><i><b>Ваша сила воли была так велика, что вы толковали небесные знаки не как дурные предзнаменования, которых следует бояться, а как направляющие образы, из которых вы могли извлечь знания о долине.</b></i></p><p>Можете потратить <energy>. Если сделали это, проведите проверку <conviction>, чтобы изучить знаки. +2, если вы <i>сосредоточенный</i>, и +4, если у вас есть отметка тайны.<br><b>≥12:</b>  Вам открылись ответы на важные вопросы. Добавьте <lore>. Получите <energy> и <major_boost> к любой характеристике.<br><b>10-11:</b>  В вашем разуме зародилась идея. Добавьте <lore>. Получите <major_boost> к <awareness>.<br><b>8-9:</b>  Вы нашли некоторое утешение в знакомых знаках. Получите <major_boost> к <awareness>.<br><b>1-7:</b>  В этот раз вам не открылось ничего ценного в небесных явлениях. Без эффекта.</p>","en":""},"code-ru":"ВЩ46","marks":[{"label":"","image":"mystery"}]},{"code":"it55","id":"moon-it55","icon":"moon","description":{"ru":"<p><i><b>В тишине вы размышляли о значении луны. Об этой далёкой и чуждой небесной форме бытия, чьи очертания искривляются и меняются и чья поверхность кажется холодной и покрытой рубцами, словно ледник. Луна заставила вас задуматься о понятиях скрытности, одиночества и податливости. Возможно, вам следовало оставить здесь небольшую пирамиду из камней, чтобы запомнить эти мысли.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Поразмышляйте о пирамиде после того, как уйдёте. </b>Если на карте вашего персонажа есть отметка становления, добавьте <lore>.<br><b>Б. Оставьте талисман из лунной крови на вершине пирамиды, чтобы ощутить лёгкость.</b> Сбросьте карту предмета «Талисман из лунной крови» (ВЩ55). Если сделали это, навсегда увеличьте значение <might> своего персонажа на 1 (не более чем до 7) и добавьте ему черту «сосредоточенный». Добавьте отметку становления на сторону легенды карты своего персонажа.</p>","en":""},"code-ru":"ВЩ55","marks":[{"label":"","image":"growth"}]},{"code":"ff05","id":"moon-ff05","icon":"moon","description":{"ru":"<p><i><b>На шерсти великолепного животного вы заметили отметку, напоминающую дугу полумесяца. Следуя за существом по извилистым лесным тропам, вы вышли на поляну, озарённую ледяным светом.</b></i></p><p>Прекратите добычу припасов, затем выберите и разыграйте одно:<br><b>А. Соберите растения и воду с этой таинственной поляны.</b> Получите 3 воды и 2 коренья. <br><b>Б. С изумлением осмотритесь.</b> Добавьте <lore><lore>.</p>","en":""},"code-ru":"ДЛ05"},{"code":"fg08","id":"moon-fg08","icon":"moon","description":{"ru":"<p><i><b>В потоке ручья отражался лунный серп. Присмотревшись, вы заметили странную жидкость, сочащуюся у кромки воды.</b></i></p><p>Можете прекратить добычу припасов. Если сделали это, получите 1 лунную кровь.</p>","en":""},"code-ru":"ДП08"},{"code":"fp01","id":"moon-fp01","icon":"moon","description":{"ru":"<p><i><b>В потоке ручья вы увидели, как поверхность луны отражалась в ряби, расходившейся от плавников необычайно красивой рыбы. Вы попытались поймать эту рыбу, но она ускользала из ваших рук — так же, как и отражение луны на водной глади. Вы задумались о том...</b></i></p><p>Выберите и разыграйте одно:<br><b>А. …откуда взялась эта рыба?</b> Добавьте <major_boost> к <awareness>.<br><b>Б. …скрывается ли какое-то важное значение в такой красоте? </b>Добавьте <lore><lore>.</p><p>Затем продолжите добычу припасов. Собирая ресурсы с этой карты, вы не получаете рыбу как бонусный ресурс.</p>","en":""},"code-ru":"ДС01"},{"code":"fp08","id":"moon-fp08","icon":"moon","description":{"ru":"<p><i><b>Свет далёкой луны блестел на панцире хищника. Возможно, вам стоит избежать встречи с этим существом…</b></i></p><p>Перед тем как продолжить добычу припасов, выберите и разыграйте одно:<br><b>А. Понаблюдайте за хищником, пока тот рыщет в поисках добычи.</b> Добавьте <lore>.<br><b>Б. Пройдитесь против ветра, чтобы существо не почуяло вас. </b>Потратьте <lore>, чтобы убрать 1 карту с хищником из области добычи.</p>","en":""},"code-ru":"ДС08"},{"code":"ac03","id":"moon-ac03","icon":"moon","description":{"ru":"<p><i><b>Целитель бросает палку к вашим ногам, задирает морду к луне и протяжно, тоскливо воет, а затем снова хватает палку и яростно мотает её из стороны в сторону.</b></i></p><p>Вы можете сбросить 1 жетон еды, чтобы получить 1 дерево.</p>","en":""},"code-ru":"ЖК03"},{"code":"kn17","id":"moon-kn17","icon":"moon","description":{"ru":"<p><i><b>Вам не терпелось узреть величие лунного серпа.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Найдите на стене отметку лунной славы. </b>Если на стене первобытной пещеры есть отметка <moon>, можете потратить <lore>, чтобы получить 1 карту легенды с отметкой <moon>.<br><b>Б. Оставьте на стене отметку лунной красоты. </b>На стене первобытной пещеры изобразите историю о величии луны, включив в неё отметку <moon>.</p>","en":""},"code-ru":"ЗБ17"},{"code":"ci01","id":"moon-ci01","icon":"moon","description":{"ru":"<p><i><b>Луна мерцала между горами — как единственный знакомый вам лик в неизведанной долине.</b></i></p><p>Если у вас нет <boost>, можете потратить <energy>, чтобы получить <major_boost> к <conviction>.</p>","en":""},"code-ru":"ИО01"},{"code":"hx01a","id":"moon-hx01a","icon":"moon","description":{"ru":"<p><i><b>Невероятные размеры черепа, возвышающегося перед вами, не поддавались пониманию. Откуда он взялся? Где остальные его кости? Были ли когда‑то существа большего размера, чем чудища? Было ли это… человеком? Пока вы размышляли, все возможные ответы словно ускользали от вас.</b></i></p><p>Проведите проверку <awareness>, чтобы найти ответы. +2 за каждую вашу черту и +2 за каждую вашу отметку.<br><b>≥30:</b>  Возможно, сама загадка была важнее ответа. Добавьте <lore><lore><lore>. Получите карту знаний «Вовне» (ЗБ20). <br><b>1-29:</b>  Видимо, некоторые загадки невозможно разгадать, но вы попытаетесь. Добавьте к целям карту «Пройдите по ледяному покрову» (ЦА06).</p>","en":""},"code-ru":"ОБ01a"},{"code":"ja05","id":"moon-ja05","icon":"moon","description":{"ru":"<p><i><b>Когда вы сидели в одиночестве, луна встретила вас дружеским светом. Её лик мерцал высоко в небе, но вам казалось, что вы могли бы дотянуться до него. Вы подумали о том, что ваши друзья видят ту же самую луну…</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Поймите, что вы не так уж и одиноки.</b> Если на стене первобытной пещеры есть отметка <moon>, добавьте <lore> и получите <minor_boost> к <conviction>.<br><b>Б. Погрузитесь в тайны луны. </b>Добавьте карту «Познайте кровь луны» (ЦЯ02) к целям.</p>","en":""},"code-ru":"ПА05"},{"code":"je06","id":"moon-je06","icon":"moon","description":{"ru":"<p><i><b>Луна взирала на столкновение спокойно и молчаливо. Вы посмотрели на неё, и в вашем сознании возникла идея. Возможно, если бы вы смогли передать это чувство другим, вам удалось бы разогнать недоброжелателей…</b></i></p><p>Вместо розыгрыша этой карты пути можете провести проверку <conviction>, чтобы остановить насилие. +2, если вы <i>осторожный</i>.<br><b>≥11:</b>  Вы были красноречивы, и враждебно настроенные люди разошлись. Уберите <unrest><unrest>. Верните в коробку карту ПР06.<br><b>6-10:</b>  Ваша речь убедила людей отступить, но лишь на время. Уберите <unrest>.<br><b>1-5:</b>  Раздались крики — люди были разъярены вашими изречениями. Добавьте <unrest><unrest>. </p>","en":""},"code-ru":"ПР06"},{"code":"pv02","id":"moon-pv02","icon":"moon","description":{"ru":"<p><i><b>Луна отражалась на поверхности воды — такая далёкая и такая близкая одновременно. Вы потянулись к её контурам на воде и увидели на дне нечто неожиданное.</b></i></p><p>Можете прекратить рыбалку. Если сделали это, проведите проверку <dexterity>, чтобы вытащить неизвестный предмет. +2, если у вас есть <i>копьё</i>, и +4, если у вас есть <i>сеть</i>. Также +1 за каждую потраченную <lore>.<br><b>≥13:</b>  Вы вытащили из воды необычный предмет. Если ни у кого из персонажей, животных-компаньонов или в сооружении нет предмета «Симбиотическое яйцо» (ВЩ93), получите его.<br><b>1-12:</b>  Вы упали в реку. Разыграйте эффект происшествия (<mishap>) в зависимости от особенности местности, где рыбачили (см. в правилах игры на с. 41).</p>","en":""},"code-ru":"РД02"},{"code":"sn02","id":"moon-sn02","icon":"moon","description":{"ru":"<p><i><b>Вы смотрели, как Целитель воет на луну. Что он пытался сказать великому ночному светилу своим задушевным пением? </b></i></p><p>Посмотрите верхнюю карту колоды ночи. Если её знамение — <moon>, добавьте <lore>. Затем верните её на верх или положите под низ колоды.</p>","en":""},"code-ru":"СЖ02"},{"code":"st13","id":"moon-st13","icon":"moon","description":{"ru":"<p><i><b>С высоты памятника на фоне ярко‑голубого неба вы увидели бледную луну, нетерпеливо ожидающую, когда закончится день и наступит ночь. Эта луна была предвестником всего неизведанного, что ждало вас впереди.</b></i></p><p>Получите <major_boost> к <awareness>.</p>","en":""},"code-ru":"СР13"},{"code":"st26","id":"moon-st26","icon":"moon","description":{"ru":"<p><i><b>Вас манило то странное место, куда вели таинственные врата. Вы собрались с силами, чтобы…</b></i></p><p>Разыграйте первое, что можете:<br><b>А. ...ступить на знакомую землю. </b>Если на карте вашего персонажа есть отметка Звёздного моря [i], можете переместить этого персонажа на участок местности Звёздного моря с пещерой.<br><b>Б. ...испытать силу духа и шагнуть в неизвестность. </b>Проведите проверку <conviction>. +2, если вы <i>отважный</i>, и +4, если у вас есть отметка лунной крови [ii]. <br><b>≥14:</b>  <outcome> 913.<br><b>8-13:</b>  <outcome> 881.<br><b>1-7:</b>  Вы потеряли решимость при виде бледного пыльного пейзажа. Потеряйте <energy>.</p>","en":""},"code-ru":"СР26","marks":[{"label":"i","image":"starlitsea"},{"label":"ii","image":"moonblood"}]},{"code":"vw02","id":"moon-vw02","icon":"moon","description":{"ru":"<p><i><b>Вы заметили вход в пещеру на уступе прямо под вами. Любопытство взяло верх, но едва вы успели спуститься, как камни под вами обрушились!</b></i></p><p>Получите 2 любых минеральных материала. Затем, если у вас нет «Верёвки», получите <major_injury>.</p>","en":""},"code-ru":"УВ02"},{"code":"vv05","id":"moon-vv05","icon":"moon","description":{"ru":"<p><i><b>Ваш взгляд остановился на трёх странных столпах, которые отзывались гулким эхом. Постепенно вас окутало тоской, словно осенним инеем. Вы ощутили, как где‑то на границе сознания до вас доносятся голоса из прошлого.</b></i></p><p>Можете пройти проверку <awareness>, чтобы внять голосам из прошлого. +2, если вы <i>сосредоточенный</i>. Также +1 за каждую потраченную <lore> (не более +3).<br><b>≥12:</b>  Вы прислушались к шёпотам голосов, и ваш разум отправился в путешествие с легендами прошлых веков. Выберите отметку на стене первобытной пещеры и добавьте её на сторону легенды карты своего персонажа. Если на стене первобытной пещеры нет отметки, которой ещё нет на карте персонажа, добавьте <lore><lore>.<br><b>8-11:</b>  Вас затянуло в хор голосов. Потеряйте <energy> и получите черту «сосредоточенный». <br><b>1-7:</b>  Вы затерялись среди гула невнятных голосов. Потеряйте <energy>.</p>","en":""},"code-ru":"УД05"},{"code":"ss01","id":"moon-ss01","icon":"moon","description":{"ru":"<p><i><b>Вы вглядывались в глубины тёмного моря, которое казалось бездонным. В ваш разум медленно проникало желание узнать, что же скрывается там, в этой чёрной пустоте.</b></i></p><p>Проведите проверку <conviction>, чтобы сопротивляться притяжению бездны. +2, если вы <i>неукротимый </i>или <i>мудрый</i>. Вычтите 4 из своего результата проверки, если вы <i>любознательный</i>.<br><b>≥14:</b>  Вы не поддались зову бездны. Назначьте <conviction> значение «7». Получите черту «сосредоточенный». Добавьте отметку становления на сторону легенды карты своего персонажа.<br><b>6-13:</b>  Вы оступились и едва не упали. Получите <minor_injury>. Получите черту «осторожный».<br><b>1-5:</b>  <outcome> 899.</p>","en":""},"code-ru":"УЗ01","marks":[{"label":"","image":"growth"}]},{"code":"sp02","id":"moon-sp02","icon":"moon","description":{"ru":"<p><i><b>Гигантские камни поднимались из земли перед вами. Обходя их, вы задумались, не образуют ли они какой‑то узор. Возможно, его будет видно с линии хребта на севере.</b></i></p><p>Можете провести проверку <conviction>, чтобы подняться на хребет. +2, если у вас есть «Верёвка», и +2, если у вас есть «Скальный крюк». Также +1 за каждую потраченную <lore> (не более +3).<br><b>≥12:</b>  Вы без происшествий поднялись на хребет. На вершине, глядя через пропасти, вы увидели, что камни образуют серп, напоминающий лунный. Затем выберите одно: добавьте <lore><lore> или посмотрите 3 верхние карты колоды ночи и положите любые из них под низ колоды.<br><b>6-11:</b>  Вы растеряли всю свою решимость и вернулись на более безопасную землю. Потеряйте <energy> и получите черту «осторожный». <br><b>1-5:</b>  Вы упали на дно пропасти, и вам понадобился целый день, чтобы выбраться оттуда. Получите <major_injury> и потеряйте <energy>.</p>","en":""},"code-ru":"УП02"},{"code":"pr01b","id":"moon-pr01b","icon":"moon","description":{"ru":"<p><i><b>Вы стали замечать серп луны повсюду: не только в ночном небе, но и в искусстве вашего народа и в очертаниях самой долины. Хоть некоторые видели в лунном серпе холодное, бесчувственное и зловещее предзнаменование неизведанного, вам он казался проводником, манящим в глубины загадок. «Помни, — словно говорила луна, — есть знания, которые стоит искать даже в темноте. Наблюдай за всем вокруг. Тайн много».</b></i></p><p>Без эффекта.</p>","en":""},"code-ru":"ФП01Н"},{"code":"gz01","id":"moon-gz01","icon":"moon","description":{"ru":"<p><i><b>Легенды вашего народа гласили, что стада зверей часто паслись в местах с густой растительностью.</b></i></p><p>Можете потратить <lore>, чтобы поместить жетон тайны на участок местности без персонажа. Выбирайте участок с лесом или степью, если возможно.</p>","en":""},"code-ru":"ЦЯ01"},{"code":"gz02","id":"moon-gz02","icon":"moon","description":{"ru":"<p><i><b>Вы вспомнили рассказы о том, как при свете луны в глубоких пещерах мерцает лунная кровь.</b></i></p><p>В следующий раз, когда будете добывать ископаемые в пещере в течение этого дня, считайте, что выполнение этого действия стоит <energy>.</p>","en":""},"code-ru":"ЦЯ02"},{"code":"gz13","id":"moon-gz13","icon":"moon","description":{"ru":"<p><i><b>Луна сияла в вышине, словно приглашая вас постичь её тайны.</b></i></p><p></p><p>В течение следующего дня, если  <moon>— не текущее знамение, любой персонаж может потратить <lore>, чтобы считать <moon> текущим знамением до конца дня.</p>","en":""},"code-ru":"ЦЯ13"},{"code":"bh1","id":"moon-bh1","icon":"moon","description":{"ru":"<p><i><b>В лунном свете тусклый мох на каменной коже чудища блестел и словно светился изнутри. Вы были поражены грубой красотой этого могучего существа.</b></i></p><p>До конца текущего испытания стоимость изучения этого чудища снижена до <lore>.</p>","en":""},"code-ru":"ЧД1"},{"code":"bh3","id":"moon-bh3","icon":"moon","description":{"ru":"<p><i><b>Лунный свет мерцал на массивной полусфере, которая венчала спину чудища. Как это существо могло быть связано с ночным светилом?</b></i></p><p>До конца текущего испытания стоимость изучения этого чудища снижена до <lore>.</p>","en":""},"code-ru":"ЧД3"},{"code":"it36","id":"star-it36","icon":"star","description":{"ru":"<p><i><b>По мере того как сгущались сумерки, пользоваться картой становилось всё сложнее. Тогда вы обратились к звёздам, чтобы они указали вам путь.</b></i></p><p>До конца этого дня, когда выполняете действие перемещения, прежде чем взять карту пути, получайте <major_boost> к <awareness>.</p>","en":""},"code-ru":"ВЩ36"},{"code":"it46","id":"star-it46","icon":"star","description":{"ru":"<p><i><b>Вас вели знамения вашего народа.</b></i></p><p>Можете потратить <energy>. Если сделали это, проведите проверку <conviction>, чтобы изучить знаки. +2, если вы <i>сосредоточенный</i>, и +4, если у вас есть отметка тайны. <br><b>≥12:</b>  У вас возникла новая идея! Добавьте <lore>. Получите <energy>. Получите <major_boost> к <dexterity>.<br><b>10-11:</b>  В вашем разуме зародилась мысль. Добавьте <lore> и получите <major_boost> к <dexterity>.<br><b>8-9:</b>  Вы думали, ходя кругами и разминая мышцы. Получите <major_boost> к <dexterity>. <br><b>1-7:</b>  В этот раз вы не смогли прочесть знаки. Без эффекта.</p>","en":""},"code-ru":"ВЩ46","marks":[{"label":"","image":"mystery"}]},{"code":"it51","id":"star-it51","icon":"star","description":{"ru":"<p><i><b>В тишине вы размышляли о значении звёзд. Они текли по ночному небу, как река, и в то же время каждая из них словно была острым уколом ножа из речного камня в темноте. Звёзды заставили вас задуматься о понятиях движения и разделения. Возможно, вам следовало оставить здесь небольшую пирамиду из камней, чтобы запомнить эти мысли.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Сложите пирамиду из камней как небольшое свидетельство вашего пути. </b>Если на карте вашего персонажа есть отметка становления, добавьте <lore>.<br><b>Б. Положите талисман из речного камня на вершину пирамиды, чтобы идеально завершить её. </b>Сбросьте карту предмета «Талисман из речного камня» (ВЩ51). Если сделали это, навсегда увеличьте значение <dexterity> своего персонажа на 1 (не более чем до 7) и добавьте ему черту «хитрый». Добавьте отметку становления на сторону легенды карты своего персонажа.</p>","en":""},"code-ru":"ВЩ51","marks":[{"label":"","image":"growth"}]},{"code":"fm02","id":"star-fm02","icon":"star","description":{"ru":"<p><i><b>Всматриваясь в ручей в поисках рыбы, на мгновение вы увидели крошечные светящиеся точки, отражённые от поверхности воды. Вы подняли глаза в ночное небо и сквозь клубящиеся пурпурные облака заметили звёзды. Хоть они и были далеки, но вам стало спокойнее при виде чего‑то знакомого в этом чужом месте.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Найдите утешение в знакомых звёздах. </b>Получите <major_boost> к <conviction>, затем продолжите добычу припасов.<br><b>Б. Примите это как знак и перестаньте испытывать удачу.</b> Получите 2 воды и <major_boost> к двум любым характеристикам. Затем прекратите добычу припасов.</p>","en":""},"code-ru":"ДД02"},{"code":"ff07","id":"star-ff07","icon":"star","description":{"ru":"<p><i><b>Символ на отпечатке напомнил вам звезду. Вы двинулись по следам вглубь леса, но заблудились и потеряли счёт времени.</b></i></p><p>После того как завершите добычу припасов, выберите и разыграйте одно:<br><b>А. Вернитесь по своим следам. </b>Добавьте <lore>.<br><b>Б. Продолжите путь и доберитесь до неожиданного места.</b> Переместите своего персонажа на участок местности с лесом (не берите карту пути).</p>","en":""},"code-ru":"ДЛ07"},{"code":"fg01","id":"star-fg01","icon":"star","description":{"ru":"<p><i><b>Следы пестрели знаками, напоминающими звёзды...</b></i></p><p>После того как завершите добычу припасов, выберите и разыграйте одно:<br><b>А. Вернитесь по своим следам.</b> Добавьте <lore>.<br><b>Б. Продолжите путь и доберитесь до неожиданного места. </b>Переместите своего персонажа на участок местности с поляной (не берите карту пути).</p>","en":""},"code-ru":"ДП01"},{"code":"kn20","id":"star-kn20","icon":"star","description":{"ru":"<p><i><b>Когда ваши глаза наполнились звёздным светом, вам открылась истина мироздания. Вы видели, как огромные глыбы падали с неба, созидая этот мир, а следом кубастые глыбы разбивали извечную бездну. Цивилизации возникали и превращались в прах. Чудища рождались и замолкали навеки... Когда вы почувствовали, что были больше не в силах это выносить, вас отбросило обратно в привычный мир. Но ваш разум навсегда запечатлел частицу истинного знания.</b></i></p><p>Ваша община получает силу мантии «Провидец» (MA00).</p>","en":""},"code-ru":"ЗБ20"},{"code":"cn04","id":"star-cn04","icon":"star","description":{"ru":"<p><i><b>Следуя по отметкам в виде звёзд на лепестках огромных цветов, вы нашли лужу из тягучего сока, капающего с растения.</b></i></p><p>Получите 3 смолы.</p>","en":""},"code-ru":"ИЖ04"},{"code":"ju03","id":"star-ju03","icon":"star","description":{"ru":"<p><i><b>Самая яркая звезда привлекла ваш взгляд к никем ранее не замеченному узору...</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Насладитесь блеском звезды. </b>Если на стене первобытной пещеры есть отметка <star> или если в долине нет неисследованных участков местности, добавьте <lore>.<br><b>Б. Посмотрите туда, куда указывает звезда. </b>Если в долине есть неисследованные участки местности, возьмите любой из них, рассмотрите в течение 30 секунд, затем поместите обратно неисследованной стороной вверх. На стене первобытной пещеры изобразите историю о созвездии, включив в неё отметку открытия и отметку <star>.</p>","en":""},"code-ru":"ПН03","marks":[{"label":"","image":"discovery"}]},{"code":"ju11","id":"star-ju11","icon":"star","description":{"ru":"<p><i><b>Вас качало на воде, но у вас получилось остановить взгляд на звёздах. Следуя им, вы смогли выплыть на берег.</b></i></p><p>Вместо того чтобы разыгрывать эту карту пути, можете переместить своего персонажа на участок местности с рекой (не берите новую карту пути).</p>","en":""},"code-ru":"ПН11"},{"code":"je01","id":"star-je01","icon":"star","description":{"ru":"<p><i><b>Знакомая звезда горела над головой, и вы восприняли это как благоприятное предзнаменование о предстоящей встрече.</b></i></p><p>Добавьте <minor_boost> к <conviction>. Если вы <i>хитрый</i>, вместо этого добавьте <major_boost> к любой характеристике.</p>","en":""},"code-ru":"ПР01"},{"code":"jt01","id":"star-jt01","icon":"star","description":{"ru":"<p><i><b>Один из лепестков был отмечен звёздами. Он оторвался от цветка и уплыл в небо, исчезая из виду.</b></i></p><p>Добавьте <lore><lore>.</p>","en":""},"code-ru":"ПС01"},{"code":"pv11","id":"star-pv11","icon":"star","description":{"ru":"<p><i><b>Под поверхностью воды вы заметили тёмную фигуру, которая переливалась звёздным светом.</b></i></p><p>Добавьте карту «Подружитесь с речным бегуном» (ЦЖ15) к целям. После рыбалки верните в коробку карту РД11.</p>","en":""},"code-ru":"РД11"},{"code":"ps02","id":"star-ps02","icon":"star","description":{"ru":"<p><i><b>На поверхности ртутного моря сверкал прохладный звёздный свет. Его след вёл вас к ледяному мосту, пересекающему бурлящие воды.</b></i></p><p>Добавьте <lore>. После того как закончите рыбалку, переместите своего персонажа на соседний участок местности (не берите карту пути).</p>","en":""},"code-ru":"РЗ02"},{"code":"st13","id":"star-st13","icon":"star","description":{"ru":"<p><b><i>В сумерках вы сидели на вершине памятника и смотрели, как небо заполняется звёздами, пронзающими черноту.</i></b></p><p>Получите <major_boost> к <dexterity>.</p>","en":""},"code-ru":"СР13"},{"code":"vw04","id":"star-vw04","icon":"star","description":{"ru":"<p><b><i>Пока дым душил ваши лёгкие, в тлеющем лесном пепле вы отыскали одинокий, но полный надежды росток.</i></b></p><p>Получите <major_boost> к <conviction>. Можете потратить <lore><lore><lore>, чтобы убрать <unrest>. Затем получите <major_disease> (если у вас есть <i>накидка</i>, вместо этого получите <minor_disease>).</p>","en":""},"code-ru":"УВ04"},{"code":"vv07","id":"star-vv07","icon":"star","description":{"ru":"<p><i><b>Внутри огромного черепа вы увидели узор из трещин, который напомнил вам о далёких звёздах. Какие из них освещали путь этому гиганту?</b></i></p><p>Раскройте 3 верхние карты колоды пути. Можете положить их на верх или под низ колоды в любом порядке. Затем, если вы <i>сосредоточенный</i>, добавьте <lore>.</p>","en":""},"code-ru":"УД07"},{"code":"ss03","id":"star-ss03","icon":"star","description":{"ru":"<p><i><b>Вы стояли на вершине одинокого холма, и ночное небо раскинулось над вами, словно наполнив вас собой. Звёзды смотрели на вас.</b></i></p><p>Проведите проверку <awareness>, чтобы сосредоточиться. +2, если вы <i>отважный </i>или <i>изобретательный</i>, и +4, если у вас есть отметка открытия [i].<br><b>≥14:</b>  Вы были тем, кто вы есть. Навсегда назначьте <awareness> значение «7». Получите черту «сосредоточенный». Добавьте отметку становления [ii] на сторону легенды карты своего персонажа.<br><b>6-13:</b>  Наваждение прошло, но вы были потрясены. Потеряйте все <boost>.<br><b>1-5:</b>  Ваш разум терзали сомнения. Навсегда назначьте <awareness> значение «1» и получите черту «осторожный».</p>","en":""},"code-ru":"УЗ03","marks":[{"label":"i","image":"discovery"},{"label":"ii","image":"growth"}]},{"code":"sp08","id":"star-sp08","icon":"star","description":{"ru":"<p><i><b>Морена лучилась, отражая ледяное сияние небес. Остановив взгляд на ней, вы увидели мерцающий поток звёзд.</b></i></p><p>Выберите и разыграйте одно:<br><b>A. Понаблюдайте, как свет скользит по вашей руке.</b> Добавьте  <lore><lore>.<br><b>Б. Оплетите лучи шёлковым покровом.</b> Если в вашем инвентаре есть шёлк, можете сбросить его, чтобы поймать свет. Получите черту «хитрый».<br><b>В. Поглотите свет жемчужиной совершенной бездны.</b> Если у вас есть «Тёмный шар» и на стороне легенды карты вашего персонажа нет отметки становления, навсегда увеличьте значение <dexterity> персонажа на 2 (не более чем до 8), затем добавьте отметку становления на сторону легенды карты своего персонажа.</p>","en":""},"code-ru":"УП08","marks":[{"label":"","image":"growth"}]},{"code":"tt03","id":"star-tt03","icon":"star","description":{"ru":"<p><b><i>На огромном лепестке высоко над вами вы разглядели отметку, похожую на звезду.</i></b></p><p>Поместите жетон тайны на случайный соседний участок местности.</p>","en":""},"code-ru":"УС03"},{"code":"mh05","id":"star-mh05","icon":"star","description":{"ru":"<p><b><i>Сияние звёзд миллионы раз преломлялось ледяными кристаллами, которые выросли на спине шагающего хребта. </i></b></p><p>Раскройте 5 верхних карт колоды ночи и положите обратно в колоду лицевой стороной вверх, не меняя их порядок. Можете смотреть верхнюю открытую карту в любое время. Играйте с этими картами, пока все 5 не будут разыграны или колода не будет перемешана (если будете перемешивать колоду, переверните все эти карты лицевой стороной вниз).</p>","en":""},"code-ru":"УУ05"},{"code":"gn12","id":"star-gn12","icon":"star","description":{"ru":"<p><b><i>Звёзды освещали поверхность реки...</i></b></p><p>Если на участке местности с вашим персонажем есть река, озеро или болото, можете потратить <lore>, чтобы получить 1 рыбу.</p>","en":""},"code-ru":"ЦЖ12"},{"code":"bh3","id":"star-bh3","icon":"star","description":{"ru":"<p><b><i>От взгляда на звёздную россыпь над чудищем вас будто закружило в вихре. Очнувшись, вы оказались в неожиданном месте. </i></b></p><p>После встречи с этим чудищем потеряйте <energy>. Затем переместите персонажа на любой участок местности (не берите карту пути), выбрав участок с рекой, если возможно.</p>","en":""},"code-ru":"ЧД3"},{"code":"em04","id":"sun-em04","icon":"sun","description":{"ru":"<p><b><i>Солнце светило ярко, и вы начали беспокоиться, что растительность стала опасно сухой и могла легко воспламениться.</i></b></p><p>Можете потратить <lore>, чтобы получить <major_boost> к <dexterity>.</p>","en":""},"code-ru":"БР04"},{"code":"it24","id":"sun-it24","icon":"sun","description":{"ru":"<p><i><b>Светило солнце, пели птицы... Это был прекрасный день для прогулки!</b></i></p><p>До конца этого дня, когда выполняете действие перемещения, прежде чем взять карту пути, получайте <major_boost> к <dexterity>.</p>","en":""},"code-ru":"ВЩ24"},{"code":"it42","id":"sun-it42","icon":"sun","description":{"ru":"<p><b><i>Вы вдохновились красотой долины и сочинили песню.</i></b></p><p>Выполните всё, что возможно:<br><b>А. Если на вашем участке местности есть лес или степь, </b>поместите <major_boost> на карту предмета ВЩ42.<br><b>Б. Если на вашем участке местности есть гора или пропасть, </b>поместите <major_boost> на карту предмета ВЩ42.<br><b>В. Если на вашем участке местности есть озеро или река, </b>поместите <major_boost> на карту предмета ВЩ42.</p><p>В течение следующей ночи, вместо того чтобы выполнять действие <night> на карте ВЩ42, можете распределить <boost> с неё между характеристиками персонажей на своём участке местности.</p>","en":""},"code-ru":"ВЩ42"},{"code":"it45","id":"sun-it45","icon":"sun","description":{"ru":"<p><b><i>Вы почувствовали, как ваше сердце наполняется силой зверя.</i></b></p><p>Проведите проверку <might>, чтобы обуздать первобытную силу. +2, если вы <i>сосредоточенный</i>, и +2, если у вас есть животное-компаньон.<br><b>≥12:</b>  Получите <energy><energy> и <major_boost> к <might>.<br><b>10-11:</b>  Получите <energy> и <major_boost> к <might>.<br><b>8-9:</b>  Получите <major_boost> к <might>.<br><b>1-7:</b>  В этот раз вы не смогли обуздать энергию. Без эффекта.</p>","en":""},"code-ru":"ВЩ45"},{"code":"it46","id":"sun-it46","icon":"sun","description":{"ru":"<p><b><i>Вы отказались отводить глаза. Глядя на небесный знак, вы поняли, что знамения несут в себе более глубокие истины.</i></b></p><p>Можете потратить <energy>. Если сделали это, проведите проверку <conviction>, чтобы изучить знаки.<br><b>≥12:</b>  Получите <energy> и <major_boost> к <might>. Добавьте <lore>.<br><b>10-11:</b>  Получите <major_boost> к <might>. Добавьте <lore>.<br><b>8-9:</b>  Получите <major_boost> к <might>.<br><b>1-7:</b>  В этот раз вам не удалось изучить знаки. Без эффекта.</p>","en":""},"code-ru":"ВЩ46"},{"code":"it53","id":"sun-it53","icon":"sun","description":{"ru":"<p><i><b>В тишине вы размышляли о значении солнца. О его власти как самого яркого небесного объекта. О его тепле и свете, питавших долину и делавших жизнь в ней возможной. Солнце заставило вас задуматься о понятиях человечности, бытия и управления. Возможно, вам следовало оставить здесь небольшую пирамиду из камней, чтобы запомнить эти мысли.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Сложите пирамиду как небольшое воспоминание, высеченное в камне.</b> Если на карте вашего персонажа есть отметка становления, добавьте <lore>.<br><b>Б. Положите солнечный камень на верх пирамиды и сразу ощутите спиной тепло солнца. </b>Сбросьте карту предмета «Талисман из солнечного камня» (ВЩ53). Если сделали это, навсегда увеличьте значение <awareness> своего персонажа на 1 (не более чем до 7) и добавьте ему черту «изобретательный». Добавьте отметку становления на сторону легенды карты своего персонажа.</p>","en":""},"code-ru":"ВЩ53","marks":[{"label":"","image":"growth"}]},{"code":"ff02","id":"sun-ff02","icon":"sun","description":{"ru":"<p><b><i>Вы заметили странный отпечаток копыта на земле, напомнивший вам солнце — знак изобилия и роста.</i></b></p><p>Разыграйте первое, что можете:<br><b>А. Насладитесь тёплыми солнечными лучами. </b>Если на стене первобытной пещеры есть отметка <sun>, получите <major_boost> к любой характеристике. Затем продолжите добычу припасов.<br><b>Б. Пройдите по залитой солнцем тропе к изобильной поляне. </b>Получите 1 орех, 1 злак, 1 гриб, 1 волокно и 1 смолу. Добавьте <lore><lore><lore>. На стене первобытной пещеры изобразите историю о великой щедрости, включив в неё отметку <sun>. Затем прекратите добычу припасов.</p>","en":""},"code-ru":"ДЛ02"},{"code":"ff04","id":"sun-ff04","icon":"sun","description":{"ru":"<p><b><i>Жаркое полуденное солнце пробилось сквозь просветы в деревьях, и вас начала мучить жажда.</i></b></p><p>Выберите и разыграйте одно:<br><b>А. Утолите жажду. </b>Если возможно, сбросьте 1 воду из своего инвентаря, чтобы получить <major_boost> к любой характеристике. <br><b>Б. Идите дальше с пересохшим горлом. </b>Уменьшите все свои <boost> по одному разу.</p>","en":""},"code-ru":"ДЛ04"},{"code":"ff15","id":"sun-ff15","icon":"sun","description":{"ru":"<p><b><i>Проследив взглядом за лучом света, вы увидели птичье гнездо наверху дерева.</i></b></p><p>Добавьте карту «Подружитесь с пернатым созданием» (ЦЖ13) к целям. Когда закончите добычу припасов, верните в коробку карту ДЛ15.</p>","en":""},"code-ru":"ДЛ15"},{"code":"fg11","id":"sun-fg11","icon":"sun","description":{"ru":"<p><b><i>На черепе хищника вы увидели солнечную отметку. Время стирало в пыль даже сильных...</i></b></p><p>Если у вас есть <boost> к <conviction>, можете сбросить его, чтобы получить 1 ракушку или 1 клык. В противном случае получите <minor_boost> к <awareness>.</p>","en":""},"code-ru":"ДП11"},{"code":"fp15","id":"sun-fp15","icon":"sun","description":{"ru":"<p><i><b>Существо украдкой прыгало по степи перед вами. Оно казалось не таким пугливым, как другие, и вы разглядели солнечную отметку на его мехе.</b></i></p><p>Добавьте карту «Подружитесь с полёвками» (ЦЖ17) к целям. Когда закончите добычу припасов, верните в коробку карту ДС15.</p>","en":""},"code-ru":"ДС15"},{"code":"ac01","id":"sun-ac01","icon":"sun","description":{"ru":"<p><i><b>Солнечные лучи скользят по косматой шерсти Вьюка. Он тихо мычит, когда вы похлопываете его по тёплому боку.</b></i></p><p>Получите <minor_boost> к <conviction>.</p>","en":""},"code-ru":"ЖК01"},{"code":"ac06","id":"sun-ac06","icon":"sun","description":{"ru":"<p><i><b>Воришка юрко шныряет меж теней и солнечных бликов, а затем возвращается с какой-то мелкой находкой.</b></i></p><p>Если для вашего региона есть колода добычи припасов, возьмите карту из неё и выберите одно из природных богатств с этой карты, если возможно, затем получите соответствующий ресурс.</p>","en":""},"code-ru":"ЖК06"},{"code":"ca05","id":"sun-ca05","icon":"sun","description":{"ru":"<p><i><b>Растения долины жадно впитывали тёплые солнечные лучи.</b></i></p><p>Можете потратить <energy>, чтобы добавить <lore>.</p>","en":""},"code-ru":"ИА05"},{"code":"cb07","id":"sun-cb07","icon":"sun","description":{"ru":"<p><i><b>Символ солнца был для вас мощным образом, напоминавшим о безграничных возможностях, что таились в каждом дне вашего бытия.</b></i></p><p>Если на стене первобытной пещеры есть отметка <sun>, можете потратить <lore>, чтобы добавить <major_boost> к любой характеристике.</p>","en":""},"code-ru":"ИБ07"},{"code":"cy01","id":"sun-cy01","icon":"sun","description":{"ru":"<p><b><i>Нежные лучи солнца пригревали, и вам захотелось приятно потянуться.</i></b></p><p>Можете потратить <energy>, чтобы добавить <minor_boost> к <might> или <dexterity>.</p>","en":""},"code-ru":"ИЕ01"},{"code":"jb01","id":"sun-jb01","icon":"sun","description":{"ru":"<p><b><i>Вы продолжали копать, пока свет солнца дразняще мерцал на чём‑то глубоко в яме...</i></b></p><p>Проведите проверку <conviction>, чтобы продолжить копать. +2, если вы <i>изобретательный</i>, и +4, если у вас есть <dig>. Также +1 за каждую потраченную <lore> (не более +3).<br><b>≥14:</b>  Вы выкопали камень, не похожий ни на один из виденных вами. Если ни у кого из персонажей, животных-компаньонов или в сооружении нет предмета «Расколотый камень» (ВЩ88), получите его. <br><b>1-13:</b>  Вы выбились из сил. Потеряйте <energy><energy>.</p>","en":""},"code-ru":"ПЧ01"},{"code":"pv09","id":"sun-pv09","icon":"sun","description":{"ru":"<p><i><b>Мягкие солнечные переливы на воде направили ваш взгляд к по‑настоящему огромной рыбе. Она могла бы стать легендарной добычей!</b></i></p><p>До конца этой рыбалки считайте, что состав верхнего течения насчитывает 5 рыб, а его базовая сложность равна 8. Если успешно разыграете одну или несколько областей заброса в этом течении, добавьте <lore><lore> и на стене первобытной пещеры изобразите историю о самой большой рыбе, включив в неё отметку изобилия. Если потерпите неудачу, потеряйте 1 предмет, который вы использовали для рыбалки, и получите <major_injury>.</p>","en":""},"code-ru":"РД09","marks":[{"label":"","image":"plenty"}]},{"code":"ps01","id":"sun-ps01","icon":"sun","description":{"ru":"<p><b><i>Солнечный свет мерцал на тёмной поверхности воды, но вы не чувствовали тепла.</i></b></p><p>Добавьте <lore>. Если вы <i>сосредоточенный</i>, вместо этого добавьте <lore><lore>.</p>","en":""},"code-ru":"РЗ01"},{"code":"st13","id":"sun-st13","icon":"sun","description":{"ru":"<p><i><b>Вы поднялись по ступеням к памятнику, чтобы полюбоваться восходящим солнцем, идеально обрамлённым круглым проёмом в центре монумента.</b></i></p><p>Получите <minor_boost> к любой характеристике.</p>","en":""},"code-ru":"СР13"},{"code":"vw01","id":"sun-vw01","icon":"sun","description":{"ru":"<p><i><b>Вопреки здравому смыслу, вы отправились в поход, чтобы получше осмотреться. Путь вам преградила лава, извергающаяся из вулкана!</b></i></p><p>Поместите жетон тайны на соседний участок местности, выбрав неисследованный, если возможно. Затем, если у вас нет «Трости», сбросьте 2 случайных ресурса из своего инвентаря.</p>","en":""},"code-ru":"УВ01"},{"code":"sp04","id":"sun-sp04","icon":"sun","description":{"ru":"<p><i><b>С другого хребта вы заметили тёмные отметины на поверхности ближайшего плоскогорья. Вам стоило подняться повыше, чтобы лучше их рассмотреть.</b></i></p><p>Можете провести проверку <might>, чтобы подняться. +2, если у вас есть «Трость». Также +2 за каждую потраченную <lore> (не более +6).<br><b>≥12:</b>  Вы поднялись и увидели, что узор очень похож на солнце. Это не показалось вам совпадением, но какой смысл здесь таился? Вы размышляли о вероятностях. Если на стене первобытной пещеры есть отметка <sun>, добавьте <lore><lore>. В противном случае на стене первобытной пещеры изобразите историю о величественном пейзаже, включив в неё отметку Поднебесной равнины и отметку <sun>. Затем ваша община получает силу мантии «Первопроходец» (MA10).<br><b>1-11:</b>  Вы смертельно устали в своём путешествии. Потеряйте <energy><energy>.</p>","en":""},"code-ru":"УП04","marks":[{"label":"","image":"skyreachplateau"}]},{"code":"tt05","id":"sun-tt05","icon":"sun","description":{"ru":"<p><b><i>Перед вами открывалась впадина, отмеченная солнцем. Сквозь неё мерцал свет.</i></b></p><p>Можете переместить своего персонажа на другой участок Сплетения или участок, соседний с любым участком Сплетения (не берите карту пути).</p>","en":""},"code-ru":"УС05"},{"code":"mh01","id":"sun-mh01","icon":"sun","description":{"ru":"<p><i><b>Когда солнце было в зените, вы отважились взобраться на спину шагающего хребта и посмотрели вдаль через море тумана. Жаркое солнце отразилось от гладкой поверхности огромного панциря неподалёку, и внезапно на ваших глазах он сместился! Это было почти незаметно, но вам не могло показаться. Раздался гул.</b></i></p><p>Получите черту «неукротимый». Если вы уже неукротимый, вместо этого добавьте <lore>.</p>","en":""},"code-ru":"УУ01"},{"code":"gb10","id":"sun-gb10","icon":"sun","description":{"ru":"<p><b><i>Вы почувствовали тепло солнечных лучей, и это придало вам уверенности.</i></b></p><p>Можете потратить <lore>, чтобы получить <major_boost> к <conviction>.</p>","en":""},"code-ru":"ЦБ10"}]'),I={version:R,lastUpdated:U,omens:E},b={en:{selectIcon:"Select icon",enterNumber:"Enter code",searchButton:"Seek Omen",noOmen:"Omen Unfound",repeatableTrue:"Repeatable",repeatableFalse:"Unique",thisOmen:"This omen is",title:"OMENS",comet:"COMET",cloud:"CLOUD",moon:"MOON",star:"STAR",sun:"SUN"},ru:{selectIcon:"Выберите иконку",enterNumber:"Введите код",searchButton:"Проверить примету",noOmen:"Примета не найдена",repeatableTrue:"Повторяемая",repeatableFalse:"Уникальная",thisOmen:"Эта примета",title:"Знамения",comet:"Комета",cloud:"Облако",moon:"Луна",star:"Звезда",sun:"Солнце"}},B=[{name:"Comet",image:p.comet},{name:"Cloud",image:p.cloud},{name:"Moon",image:p.moon},{name:"Star",image:p.star},{name:"Sun",image:p.sun}];function q(){const{language:c,_:T}=O(),{search:a}=S(),y=C(),[t,m]=n.useState("Comet"),[s,h]=n.useState([]),[d,f]=n.useState(null),[u,l]=n.useState(""),[v,g]=n.useState(!1),_=async()=>I;n.useEffect(()=>{_().then(e=>{h(e.omens)})},[]),n.useEffect(()=>{const e=new URLSearchParams(a),i=e.get("icon"),r=e.get("code");i&&typeof i=="string"&&m(i),r&&typeof r=="string"&&(l(r),s.length&&i&&w(i,r))},[a,s.length]);const k=async()=>{!u||!t||y({pathname:"/OMENS",search:`?icon=${encodeURIComponent(t)}&code=${encodeURIComponent(u)}`},{replace:!0})},w=async(e,i)=>{if(!(!i||!e)){g(!0);try{const r=c==="ru"?"code-ru":"code",x=s.find(j=>j.icon.toLowerCase()===e.toLowerCase()&&j[r].toUpperCase()===i.toUpperCase());f(x||{title:{en:b.en.noOmen,ru:b.ru.noOmen},description:{en:"",ru:""}})}catch(r){console.error("Error fetching omens:",r)}finally{g(!1)}}};return o.jsxs(o.Fragment,{children:[o.jsx(N,{}),o.jsx(M,{title:b[c].title,children:o.jsxs("div",{className:"recipes-content",children:[o.jsx("div",{className:"icon-selection",children:B.map(e=>o.jsxs("div",{className:`icon-option ${t===e.name?"selected":""}`,onClick:()=>m(e.name),children:[o.jsx("img",{src:e.image,alt:e.name}),o.jsx("span",{className:"icon-text",children:b[c][e.name.toLowerCase()]})]},e.name))}),o.jsxs("div",{className:"input-row",children:[o.jsx("input",{type:"text",className:"number-input",value:u,onChange:e=>l(e.target.value.trim()),placeholder:b[c].enterNumber}),o.jsx("button",{className:"craft-button",onClick:k,disabled:v,children:b[c].searchButton})]}),d&&o.jsxs(A,{children:[d.title?o.jsx("h3",{children:b[c].noOmen}):o.jsx(o.Fragment,{}),o.jsx(z,{text:d.description[c]}),o.jsx(L,{marks:d.marks})]})]})})]})}export{q as default};
